use clap::Parser;

#[derive(Parser)]
struct Cli {
    action: String,
    title: Option<String>,
    #[arg(long)]
    id: Option<u32>,
    #[arg(long)]
    all: bool,
}

fn add(title: &str) {
    println!("added: {title}");
}

fn list(all: bool) {
    println!("listing (all = {all})");
}

fn done(id: u32) {
    println!("done: {id}");
}

fn main() {
    let cli = Cli::parse();
    match cli.action.as_str() {
        "add" => add(&cli.title.expect("title is required")),
        "list" => list(cli.all),
        "done" => done(cli.id.expect("--id is required")),
        other => eprintln!("unknown action: {other}"),
    }
}

