use clap::{Parser, Subcommand};

#[derive(Parser)]
#[command(version, about)]
struct Cli {
    #[command(subcommand)]
    command: Command,
}

#[derive(Subcommand)]
enum Command {
    /// Add a new task
    Add { title: String },
    /// List tasks
    List {
        #[arg(long)]
        all: bool,
    },
    /// Mark a task as done
    Done { id: u32 },
}

fn main() {
    let cli = Cli::parse();
    match cli.command {
        Command::Add { title } => add(&title),
        Command::List { all } => list(all),
        Command::Done { id } => done(id),
    }
}

use std::path::{Path, PathBuf};

use clap::{Parser, Subcommand};

#[derive(Parser)]
#[command(version, about)]
struct Cli {
    /// Path to the task file
    #[arg(long, default_value = "todo.json")]
    db: PathBuf,
    #[command(subcommand)]
    command: Command,
}

fn add(db: &Path, title: &str) {
    println!("added to {}: {title}", db.display());
}

fn list(db: &Path, all: bool) {
    println!("listing {} (all = {all})", db.display());
}

fn done(db: &Path, id: u32) {
    println!("done in {}: {id}", db.display());
}

fn main() {
    let cli = Cli::parse();
    match cli.command {
        Command::Add { title } => add(&cli.db, &title),
        Command::List { all } => list(&cli.db, all),
        Command::Done { id } => done(&cli.db, id),
    }
}
